import { useState } from 'react';
import Landing from './components/Landing';
import Login from './components/Login';
import VehicleList from './components/VehicleList';
import AddVehicle from './components/AddVehicle';
import OwnerDashboard from './components/OwnerDashboard';
import RentModal from './components/RentModal';
import Confirmation from './components/Confirmation';
import './App.css';

function App() {
  const [page, setPage] = useState('landing'); // 'landing' | 'login'
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [view, setView] = useState('vehicles');
  const [selectedVehicle, setSelectedVehicle] = useState(null);
  const [reservation, setReservation] = useState(null);
  const [refreshKey, setRefreshKey] = useState(0);

  const handleLogin = (tok, usr) => {
    setToken(tok);
    setUser(usr);
  };

  const handleLogout = async () => {
    try {
      await fetch('http://localhost:3001/api/logout', {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });
    } catch (_) {}
    setUser(null);
    setToken(null);
    setView('vehicles');
    setReservation(null);
    setPage('landing');
  };

  const handleRentSuccess = (res) => {
    setSelectedVehicle(null);
    setReservation(res);
  };

  const handleBack = () => {
    setReservation(null);
    setRefreshKey((k) => k + 1);
    setView('vehicles');
  };

  if (!user && page === 'landing') {
    return <Landing onGetStarted={() => setPage('login')} />;
  }

  if (!user && page === 'login') {
    return <Login onLogin={handleLogin} onBack={() => setPage('landing')} />;
  }

  if (reservation) {
    return (
      <div className="app">
        <nav className="navbar">
          <div className="nav-logo">UniRide</div>
        </nav>
        <main className="main-content">
          <Confirmation reservation={reservation} onBack={handleBack} />
        </main>
      </div>
    );
  }

  return (
    <div className="app">
      <nav className="navbar">
        <div className="nav-logo">UniRide</div>
        <div className="nav-center">
          <button
            className={view === 'vehicles' ? 'nav-btn active' : 'nav-btn'}
            onClick={() => setView('vehicles')}
          >
            Araçlar
          </button>
          {user.role === 'owner' && (
            <>
              <button
                className={view === 'dashboard' ? 'nav-btn active' : 'nav-btn'}
                onClick={() => setView('dashboard')}
              >
                İlanlarım
              </button>
              <button
                className={view === 'add' ? 'nav-btn active' : 'nav-btn'}
                onClick={() => setView('add')}
              >
                Araç Ekle
              </button>
            </>
          )}
        </div>
        <div className="nav-user">
          <span>👤 {user.name}</span>
          <span className="role-badge">
            {user.role === 'owner' ? 'Araç Sahibi' : 'Kiracı'}
          </span>
          <button className="logout-btn" onClick={handleLogout}>
            Çıkış
          </button>
        </div>
      </nav>

      <main className="main-content">
        {view === 'vehicles' && (
          <VehicleList
            key={refreshKey}
            user={user}
            onRent={setSelectedVehicle}
          />
        )}
        {view === 'add' && user.role === 'owner' && (
          <AddVehicle
            user={user}
            onAdded={() => {
              setView('vehicles');
              setRefreshKey((k) => k + 1);
            }}
          />
        )}
      </main>

      {selectedVehicle && (
        <RentModal
          vehicle={selectedVehicle}
          user={user}
          token={token}
          onClose={() => setSelectedVehicle(null)}
          onSuccess={handleRentSuccess}
        />
      )}
    </div>
  );
}

export default App;
